import{_ as p,a0 as l,w as o,s as r,ao as d,I as i,x as a,a1 as e,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"3 個值得使用的首次亮相在 Python 3.0 中的特性 | LCTT x X-CMD","titleTemplate":false,"description":"3 個值得使用的首次亮相在 Python 3.0 中的特性 | LCTT (202105) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"3 個值得使用的首次亮相在 Python 3.0 中的特性 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"3 個值得使用的首次亮相在 Python 3.0 中的特性 | LCTT (202105) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202105/20210512 3 features that debuted in Python 3.0 you should use now","title":"3 個值得使用的首次亮相在 Python 3.0 中的特性","tag":"202105","desc":""},"relativePath":"202105/20210512 3 features that debuted in Python 3.0 you should use now.md","filePath":"[post].md"}'),h={name:"202105/20210512 3 features that debuted in Python 3.0 you should use now.md"};function u(c,s,g,k,b,f){const n=l("Link");return o(),r("div",null,[s[15]||(s[15]=d(`<h1 id="_3-個值得使用的首次亮相在-python-3-0-中的特性" tabindex="-1">3 個值得使用的首次亮相在 Python 3.0 中的特性 <a class="header-anchor" href="#_3-個值得使用的首次亮相在-python-3-0-中的特性" aria-label="Permalink to “3 個值得使用的首次亮相在 Python 3.0 中的特性”">​</a></h1><blockquote><p>探索一些未被充分利用但仍然有用的 Python 特性。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202105/20/103117me72dllr6lebk1fv.jpg" alt=""></p><p>這是 Python 3.x 首發特性系列文章的第一篇。Python 3.0 於 2008 年首次發佈，儘管它已經發布了一段時間，但它引入的許多特性都沒有被充分利用，而且相當酷。這裏有三個你應該知道的。</p><h3 id="僅限關鍵字參數" tabindex="-1">僅限關鍵字參數 <a class="header-anchor" href="#僅限關鍵字參數" aria-label="Permalink to “僅限關鍵字參數”">​</a></h3><p>Python 3.0 首次引入了<strong>僅限關鍵字參數</strong>參數的概念。在這之前，不可能指定一個只通過關鍵字傳遞某些參數的 API。這在有許多參數，其中一些參數可能是可選的函數中很有用。</p><p>請看一個特意設計的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def show_arguments(base, extended=None, improved=None, augmented=None):</span></span>
<span class="line"><span>    print(&quot;base is&quot;, base)</span></span>
<span class="line"><span>    if extended is not None:</span></span>
<span class="line"><span>        print(&quot;extended is&quot;, extended)</span></span>
<span class="line"><span>    if improved is not None:</span></span>
<span class="line"><span>        print(&quot;improved is&quot;, improved)</span></span>
<span class="line"><span>    if augmented is not None:</span></span>
<span class="line"><span>        print(&quot;augmented is&quot;, augmented)</span></span></code></pre></div><p>當閲讀調用該函數的代碼時，有時很難理解發生了什麼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>show_arguments(&quot;hello&quot;, &quot;extra&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    base is hello</span></span>
<span class="line"><span>    extended is extra</span></span>
<span class="line"><span></span></span>
<span class="line"><span>show_arguments(&quot;hello&quot;, None, &quot;extra&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    base is hello</span></span>
<span class="line"><span>    improved is extra</span></span></code></pre></div><p>雖然可以用關鍵字參數來調用這個函數，但這明顯不是最好的方法。相反，你可以將這些參數標記為僅限關鍵字：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def show_arguments(base, *, extended=None, improved=None, augmented=None):</span></span>
<span class="line"><span>    print(&quot;base is&quot;, base)</span></span>
<span class="line"><span>    if extended is not None:</span></span>
<span class="line"><span>        print(&quot;extended is&quot;, extended)</span></span>
<span class="line"><span>    if improved is not None:</span></span>
<span class="line"><span>        print(&quot;improved is&quot;, improved)</span></span>
<span class="line"><span>    if augmented is not None:</span></span>
<span class="line"><span>        print(&quot;augmented is&quot;, augmented)</span></span></code></pre></div><p>現在，你不能用位置參數傳入額外的參數：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>show_arguments(&quot;hello&quot;, &quot;extra&quot;)</span></span>
<span class="line"><span>    ---------------------------------------------------------------------------</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    TypeError                                 Traceback (most recent call last)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &lt;ipython-input-7-6000400c4441&gt; in &lt;module&gt;</span></span>
<span class="line"><span>    ----&gt; 1 show_arguments(&quot;hello&quot;, &quot;extra&quot;)</span></span>
<span class="line"><span>   </span></span>
<span class="line"><span></span></span>
<span class="line"><span>    TypeError: show_arguments() takes 1 positional argument but 2 were given</span></span></code></pre></div><p>對該函數的有效調用更容易預測：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>show_arguments(&quot;hello&quot;, improved=&quot;extra&quot;)</span></span>
<span class="line"><span>    base is hello</span></span>
<span class="line"><span>    improved is extra</span></span></code></pre></div><h3 id="nonlocal" tabindex="-1">nonlocal <a class="header-anchor" href="#nonlocal" aria-label="Permalink to “nonlocal”">​</a></h3><p>有時，函數式編程的人根據編寫累加器的難易程度來判斷一種語言。累加器是一個函數，當它被調用時，返回目前為止發給它的所有參數的總和。</p><p>在 3.0 之前，Python 的標準答案是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>class _Accumulator:</span></span>
<span class="line"><span>    def __init__(self):</span></span>
<span class="line"><span>        self._so_far = 0</span></span>
<span class="line"><span>    def __call__(self, arg):</span></span>
<span class="line"><span>        self._so_far += arg</span></span>
<span class="line"><span>        return self._so_far</span></span>
<span class="line"><span></span></span>
<span class="line"><span>def make_accumulator():</span></span>
<span class="line"><span>    return _Accumulator()</span></span></code></pre></div><p>雖然我承認有些囉嗦，但這確實有效：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>acc = make_accumulator()</span></span>
<span class="line"><span>print(&quot;1&quot;, acc(1))</span></span>
<span class="line"><span>print(&quot;5&quot;, acc(5))</span></span>
<span class="line"><span>print(&quot;3&quot;, acc(3))</span></span></code></pre></div><p>這樣做的輸出結果將是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>1 1</span></span>
<span class="line"><span>5 6</span></span>
<span class="line"><span>3 9</span></span></code></pre></div><p>在 Python 3.x 中，<code>nonlocal</code> 關鍵字可以用少得多的代碼實現同樣的行為。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def make_accumulator():</span></span>
<span class="line"><span>    so_far = 0</span></span>
<span class="line"><span>    def accumulate(arg):</span></span>
<span class="line"><span>        nonlocal so_far</span></span>
<span class="line"><span>        so_far += arg</span></span>
<span class="line"><span>        return so_far</span></span>
<span class="line"><span>    return accumulate</span></span></code></pre></div><p>雖然累加器是人為的例子，但使用 <code>nonlocal</code> 關鍵字使內部函數擁有具有狀態的的能力是一個強大的工具。</p><h3 id="擴展析構" tabindex="-1">擴展析構 <a class="header-anchor" href="#擴展析構" aria-label="Permalink to “擴展析構”">​</a></h3><p>想像一下，你有一個 CSV 文件，每一行由幾個元素組成：</p><ul><li>第一個元素是年份</li><li>第二個元素是月</li><li>其他元素是該月發表的全部文章數，每天一個條目</li></ul><p>請注意，最後一個元素是 <em>文章總數</em>，而不是 <em>每天發表的文章</em>。例如，一行的開頭可以是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>2021,1,5,8,10</span></span></code></pre></div><p>這意味着在 2021 年 1 月，第一天發表了 5 篇文章。第二天，又發表了三篇文章，使總數達到 8 篇。第三天，又發表了兩篇文章。</p><p>一個月可以有 28 天、30 天或 31 天。提取月份、日期和文章總數有多難？</p><p>在 3.0 之前的 Python 版本中，你可能會這樣寫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>year, month, total = row[0], row[1], row[-1]</span></span></code></pre></div><p>這是正確的，但它掩蓋了格式。使用<strong>擴展析構</strong>，同樣可以這樣表達：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>year, month, *rest, total = row</span></span></code></pre></div><p>這意味着如果該格式改為前綴了一個描述，你可以把代碼改成：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>_, year, month, *rest, total = row</span></span></code></pre></div><p>而不需要在每個索引中添加 <code>1</code>。</p><h3 id="接下來是什麼" tabindex="-1">接下來是什麼？ <a class="header-anchor" href="#接下來是什麼" aria-label="Permalink to “接下來是什麼？”">​</a></h3><p>Python 3.0 和它的後期版本已經推出了 12 年多，但是它的一些功能還沒有被充分利用。在本系列的下一篇文章中，我將會寫另外三個。</p><hr>`,44)),i("p",null,[s[1]||(s[1]=a("via: ",-1)),e(n,{href:"https://opensource.com/article/21/5/python-30-features"},{default:t(()=>[...s[0]||(s[0]=[a("https://opensource.com/article/21/5/python-30-features",-1)])]),_:1})]),i("p",null,[s[6]||(s[6]=a("作者：",-1)),e(n,{href:"https://opensource.com/users/moshez"},{default:t(()=>[...s[2]||(s[2]=[a("Moshe Zadka",-1)])]),_:1}),s[7]||(s[7]=a(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 譯者：",-1)),e(n,{href:"https://github.com/geekpi"},{default:t(()=>[...s[4]||(s[4]=[a("geekpi",-1)])]),_:1}),s[9]||(s[9]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:t(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:t(()=>[...s[11]||(s[11]=[a("Linux中國",-1)])]),_:1}),s[14]||(s[14]=a(" 榮譽推出",-1))])])}const _=p(h,[["render",u]]);export{x as __pageData,_ as default};
